package com.example.leavemanagement.request.application;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional(readOnly=true) public class ManagerDashboardService {private final ManagerLeaveRequestQueryService queries;public ManagerDashboardService(ManagerLeaveRequestQueryService queries){this.queries=queries;}public Dashboard dashboard(UUID managerId){var pending=queries.list(managerId,0,20,"PENDING");var approved=queries.list(managerId,0,20,"APPROVED");return new Dashboard(pending.content(),approved.content(),pending.totalElements());}public record Dashboard(List<ManagerLeaveRequestQueryService.Summary> pendingRequests,List<ManagerLeaveRequestQueryService.Summary> approvedUpcomingLeave,long pendingCount){}}
